"""Transaction and validation regression checks; run from the project root."""
import os
import sqlite3
import sys

sys.path.insert(0, os.getcwd())
from src.events import Recorder
from src.repository import balance, initialize
from src.service import transfer


def setup(autocommit=False):
    connection = sqlite3.connect(":memory:", isolation_level=None if autocommit else "")
    initialize(connection)
    connection.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    connection.commit()
    return connection


def state(connection):
    return (balance(connection, "a"), balance(connection, "b"),
            connection.execute("SELECT * FROM ledger").fetchall())


class FailingConnection:
    def __init__(self, connection, fail_at):
        self.connection = connection
        self.fail_at = fail_at
        self.calls = 0
        self.rollbacks = 0

    def fail(self):
        self.calls += 1
        if self.calls == self.fail_at:
            raise sqlite3.OperationalError("injected database failure")

    def execute(self, *args):
        self.fail()
        return self.connection.execute(*args)

    def commit(self):
        self.fail()
        self.connection.commit()

    def rollback(self):
        self.rollbacks += 1
        self.connection.rollback()


for autocommit in (False, True):
    for source, target, amount in [
        ("a", "a", 10), ("missing", "b", 10), ("a", "missing", 10),
        ("a", "b", 101), ("a", "b", 0), ("a", "b", -1),
        ("a", "b", True), ("a", "b", 1.5), ("a", "b", "10"),
    ]:
        c, p = setup(autocommit), Recorder()
        try:
            transfer(c, p, source, target, amount)
        except ValueError:
            pass
        else:
            raise AssertionError("invalid transfer accepted")
        assert state(c) == (100, 20, [])
        assert not c.in_transaction and not p.events
        c.close()

    # BEGIN, two reads, three writes, and commit must all be protected.
    for fail_at in range(1, 8):
        c, p = setup(autocommit), Recorder()
        faulty = FailingConnection(c, fail_at)
        try:
            transfer(faulty, p, "a", "b", 10)
        except sqlite3.OperationalError:
            pass
        else:
            raise AssertionError("database failure swallowed")
        assert faulty.rollbacks == 1
        assert state(c) == (100, 20, [])
        assert not c.in_transaction and not p.events
        c.close()

    c = setup(autocommit)

    class FailingPublisher:
        def publish(self, event):
            assert not c.in_transaction
            assert state(c) == (0, 120, [("a", "b", 100)])
            assert event == {"source": "a", "target": "b", "amount": 100}
            raise RuntimeError("publication failed")

    try:
        transfer(c, FailingPublisher(), "a", "b", 100)
    except RuntimeError:
        pass
    else:
        raise AssertionError("publication failure swallowed")
    assert state(c) == (0, 120, [("a", "b", 100)])
    c.close()
